# ==================================================
# Debian/Ubuntu パッケージ名マッピング
# ==================================================
# 形式: 論理名=実際のパッケージ名
# 論理名が実際のパッケージ名と同じ場合は記載不要
# ==================================================

# 開発ツール
vscode=code
libasound2=libasound2t64   # Ubuntu 24.04 / Debian trixie の t64 移行で改名

# フォント
firacode=fonts-firacode
noto-cjk=fonts-noto-cjk

# 日本語入力
fcitx5-frontends=fcitx5-frontend-all
fcitx5-configtool=fcitx5-config-qt
